SELECT count() AS Started,countIf(last_status='training_completed') AS Completed,countIf(last_status='training_abandoned') AS Abandoned FROM knowledge_analytics.sessions WHERE mode!='mock' AND $__timeFilter(started_at) AND (${mode:sqlstring}='__all' OR mode=${mode:sqlstring}) AND (${algorithm:sqlstring}='__all' OR algorithm_version=${algorithm:sqlstring}) AND (${experiment:sqlstring}='__all' OR experiment_group=${experiment:sqlstring})
